FiniteField.sum_pow_lt_card_sub_one : ∀ (K : Type u_1) [inst : Field K] [inst_1 : Fintype K],
  ∀ i < Fintype.card K - 1, ∑ x, x ^ i = 0
FiniteField.sum_pow_units : ∀ (K : Type u_1) [inst : Field K] [inst_1 : Fintype K] [inst_2 : DecidableEq K] (i : ℕ),
  ∑ x, ↑x ^ i = if Fintype.card K - 1 ∣ i then -1 else 0
descPochhammer_eval_eq_descFactorial : ∀ (R : Type u_1) [inst : Ring R] (n k : ℕ),
  Polynomial.eval (↑n) (descPochhammer R k) = ↑(n.descFactorial k)
@Polynomial.taylor_mul : ∀ {R : Type u_1} [inst : CommSemiring R] (r : R) (p q : Polynomial R),
  (Polynomial.taylor r) (p * q) = (Polynomial.taylor r) p * (Polynomial.taylor r) q
@Polynomial.taylor_apply : ∀ {R : Type u_1} [inst : Semiring R] (r : R) (f : Polynomial R),
  (Polynomial.taylor r) f = f.comp (Polynomial.X + Polynomial.C r)
@Polynomial.taylor_coeff : ∀ {R : Type u_1} [inst : Semiring R] (r : R) (f : Polynomial R) (n : ℕ),
  ((Polynomial.taylor r) f).coeff n = Polynomial.eval r ((Polynomial.hasseDeriv n) f)
@Polynomial.X_pow_dvd_iff : ∀ {R : Type u_1} [inst : Semiring R] {f : Polynomial R} {n : ℕ},
  Polynomial.X ^ n ∣ f ↔ ∀ d < n, f.coeff d = 0
@Polynomial.eval_eq_sum_range' : ∀ {R : Type u_1} [inst : Semiring R] {p : Polynomial R} {n : ℕ},
  p.natDegree < n → ∀ (x : R), Polynomial.eval x p = ∑ i ∈ Finset.range n, p.coeff i * x ^ i
Polynomial.coeff_X_add_one_pow : ∀ (R : Type u_1) [inst : Semiring R] (n k : ℕ),
  ((Polynomial.X + 1) ^ n).coeff k = ↑(n.choose k)
@ZMod.natCast_zmod_val : ∀ {n : ℕ} [NeZero n] (a : ZMod n), ↑a.val = a
ZMod.natCast_eq_natCast_iff' : ∀ (a b c : ℕ), ↑a = ↑b ↔ a % c = b % c
@Nat.Prime.dvd_factorial : ∀ {n p : ℕ}, Nat.Prime p → (p ∣ n.factorial ↔ p ≤ n)
@Finset.sum_bij : ∀ {ι : Type u_1} {κ : Type u_2} {M : Type u_3} [inst : AddCommMonoid M] {s : Finset ι} {t : Finset κ}
  {f : ι → M} {g : κ → M} (i : (a : ι) → a ∈ s → κ),
  (∀ (a : ι) (ha : a ∈ s), i a ha ∈ t) →
    (∀ (a₁ : ι) (ha₁ : a₁ ∈ s) (a₂ : ι) (ha₂ : a₂ ∈ s), i a₁ ha₁ = i a₂ ha₂ → a₁ = a₂) →
      (∀ b ∈ t, ∃ a, ∃ (ha : a ∈ s), i a ha = b) →
        (∀ (a : ι) (ha : a ∈ s), f a = g (i a ha)) → ∑ x ∈ s, f x = ∑ x ∈ t, g x

